<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { FilePenLine, Plus, Save, WandSparkles, Download, Users } from 'lucide-vue-next'
import Modal from '../components/Modal.vue'
import JournalTabs from '../components/JournalTabs.vue'
import NextPlanPicker from '../components/NextPlanPicker.vue'
import { appendPlan } from '../nextPlan'
import { queueWordExport, queuePrintExport } from '../exports'
import Pager from '../components/Pager.vue'
import DraftNotice from '../components/DraftNotice.vue'
import ConflictNotice from '../components/ConflictNotice.vue'
import HistoryPanel from '../components/HistoryPanel.vue'
import { useDraft,useConflict } from '../drafts'
import { all, api, downloadMarkdown, durationLabel, isProjectReadOnly, localDate, messageOf, notify, projectName, query, softDelete, ui } from '../api'
import type { Entity, Page, Task } from '../types'
interface TeamEntry extends Entity {project_id:string;log_date:string;person_name:string;content:string;next_plan:string;blockers:string;task_ids:string[]}
interface Snapshot {generated_at?:string;task_snapshot_semantics?:string;total_minutes?:number;missing_people?:string[];people?:Array<{person_name:string;minutes:number;submitted:boolean}>;team_entries?:Array<{id:string;version:number;person_name:string}>;tasks?:Array<{id:string;version:number}>;time_entries?:Array<{id:string;version:number}>;lan_entries?:Array<{id:string;version:number}>;lan_people?:Array<{member_id:string;person_name:string;minutes:number;submitted:boolean}>}
interface ProjectLog extends Entity {project_id:string;log_date:string;content:string;source_snapshot:Snapshot}
const props=defineProps<{revision:number}>();const emit=defineEmits<{changed:[]}>()
const exporting=ref(false)
const project=ref(''),date=ref(localDate()),entries=ref<TeamEntry[]>([]),tasks=ref<Task[]>([]),logs=ref<ProjectLog[]>([]),total=ref(0),offset=ref(0),error=ref(''),loading=ref(false),saving=ref(false),generating=ref(false),editor=ref(false),editing=ref<ProjectLog>(),entryOpen=ref(false),entrySaving=ref(false),entryError=ref(''),editingEntry=ref<TeamEntry>()
const limit=15,logForm=reactive({project_id:'',log_date:localDate(),content:'',source_snapshot:{} as Snapshot,refresh_source:false})
const entryForm=reactive({project_id:'',log_date:localDate(),person_name:'',content:'',next_plan:'',blockers:'',task_ids:[] as string[]})
const local=useDraft(()=>`project_daily_logs:${editing.value?.id||logForm.project_id+':'+logForm.log_date}`,logForm,()=>editor.value,()=>editing.value?.version)
const entryDraft=useDraft(()=>`team_daily_entries:${editingEntry.value?.id||entryForm.project_id+':new'}`,entryForm,()=>entryOpen.value,()=>editingEntry.value?.version)
const freshSource=computed({get:()=>logForm.refresh_source,set:(value:boolean)=>{logForm.refresh_source=value}})
const conflict=useConflict(),entryConflict=useConflict()
const readonly=computed(()=>isProjectReadOnly(logForm.project_id)),source=computed(()=>logForm.source_snapshot||{}),people=computed(()=>[...new Set([...tasks.value.map(t=>t.assignee),...entries.value.map(e=>e.person_name)].filter(Boolean))].sort()),projectReadonly=computed(()=>!project.value||isProjectReadOnly(project.value))
let loadRequest=0
async function load(){const request=++loadRequest,pid=project.value,day=date.value;loading.value=true;error.value='';try{const filters={project_id:pid,log_date:day};const [team,saved,tree]=await Promise.all([all<TeamEntry>('/api/team-daily-entries',filters),api<Page<ProjectLog>>(`/api/project-daily-logs?${query({project_id:pid,limit,offset:offset.value})}`),pid?api<Page<Task>>(`/api/projects/${pid}/tree`):Promise.resolve({items:[] as Task[]})]);if(request===loadRequest){entries.value=team;logs.value=saved.items;total.value=saved.total;tasks.value=tree.items}}catch(e){if(request===loadRequest)error.value=messageOf(e)}finally{if(request===loadRequest)loading.value=false}}
function canLeave(){if(saving.value||generating.value||entrySaving.value)return false;return (!editor.value||local.canLeave())&&(!entryOpen.value||entryDraft.canLeave())}
async function apply(){if(!canLeave())return;editor.value=false;offset.value=0;await load()}
async function generate(){if(!project.value||!date.value||!canLeave())return;generating.value=true;error.value='';try{const data=await api<{project_id:string;log_date:string;content:string;source_snapshot:Snapshot}>('/api/project-daily-logs/generate',{method:'POST',body:JSON.stringify({project_id:project.value,log_date:date.value})});const existing=(await api<Page<ProjectLog>>(`/api/project-daily-logs?${query({project_id:project.value,log_date:date.value,limit:1})}`)).items[0];local.persist();editing.value=existing;Object.assign(logForm,data);editor.value=true;freshSource.value=true;conflict.clear();await local.reset();local.markDirty();notify(existing?'已重新生成草稿，核对后保存才会更新原日志':'项目日志草稿已生成，请核对后保存')}catch(e){error.value=messageOf(e)}finally{generating.value=false}}
async function select(log:ProjectLog){if(!canLeave())return;try{const latest=await api<ProjectLog>(`/api/project-daily-logs/${log.id}`);editing.value=latest;Object.assign(logForm,{project_id:latest.project_id,log_date:latest.log_date,content:latest.content,source_snapshot:latest.source_snapshot});editor.value=true;freshSource.value=false;conflict.clear();await local.reset()}catch(e){error.value=messageOf(e)}}
async function save(){if(saving.value||readonly.value||!logForm.content.trim())return;saving.value=true;error.value='';const payload={project_id:logForm.project_id,log_date:logForm.log_date,content:logForm.content,...(!editing.value||freshSource.value?{source_snapshot:logForm.source_snapshot}:{}),...(editing.value?{version:editing.value.version}:{})};try{const saved=await api<ProjectLog>(editing.value?`/api/project-daily-logs/${editing.value.id}`:'/api/project-daily-logs',{method:editing.value?'PATCH':'POST',body:JSON.stringify(payload)});local.discard();editing.value=saved;Object.assign(logForm,{project_id:saved.project_id,log_date:saved.log_date,content:saved.content,source_snapshot:saved.source_snapshot});freshSource.value=false;await local.reset();notify('项目工作日志已保存');emit('changed');await load()}catch(e){error.value=messageOf(e);local.persist();if(editing.value)await conflict.capture(e,`/api/project-daily-logs/${editing.value.id}`,payload)}finally{saving.value=false}}
async function reloadConflict(){const remote=conflict.current.value?.remote as unknown as ProjectLog;if(!remote)return;local.persist();await select(remote);conflict.clear()}
async function editEntry(entry?:TeamEntry){if(entryOpen.value&&!entryDraft.canLeave())return;editingEntry.value=entry;Object.assign(entryForm,{project_id:entry?.project_id||project.value,log_date:entry?.log_date||date.value,person_name:entry?.person_name||'',content:entry?.content||'',next_plan:entry?.next_plan||'',blockers:entry?.blockers||'',task_ids:[...(entry?.task_ids||[])]});entryError.value='';entryConflict.clear();entryOpen.value=true;await entryDraft.reset()}
async function saveEntry(){if(entrySaving.value||isProjectReadOnly(entryForm.project_id))return;entrySaving.value=true;entryError.value='';const payload={...entryForm,...(editingEntry.value?{version:editingEntry.value.version}:{})};try{await api(editingEntry.value?`/api/team-daily-entries/${editingEntry.value.id}`:'/api/team-daily-entries',{method:editingEntry.value?'PATCH':'POST',body:JSON.stringify(payload)});entryDraft.discard();entryOpen.value=false;notify('人员工作记录已保存；已有项目日志需显式重新生成才会引用新内容');emit('changed');await load()}catch(e){entryError.value=messageOf(e);if(editingEntry.value)await entryConflict.capture(e,`/api/team-daily-entries/${editingEntry.value.id}`,payload)}finally{entrySaving.value=false}}
async function reloadEntry(){const remote=entryConflict.current.value?.remote as unknown as TeamEntry;if(!remote)return;entryDraft.persist();entryConflict.clear();await editEntry(remote)}
async function removeEntry(entry:TeamEntry){try{if(await softDelete('team-daily-entries',entry,`${entry.log_date} ${entry.person_name}的工作记录`)){emit('changed');await load()}}catch(e){error.value=messageOf(e)}}
async function removeLog(){if(!editing.value)return;try{if(await softDelete('project-daily-logs',editing.value,`${logForm.log_date} 项目工作日志`)){local.discard();editor.value=false;editing.value=undefined;emit('changed');await load()}}catch(e){error.value=messageOf(e)}}
async function openEntity(id:string){try{if(id.startsWith('team:')){if(!canLeave())return;const entry=await api<TeamEntry>(`/api/team-daily-entries/${id.slice(5)}`);project.value=entry.project_id;date.value=entry.log_date;await load();await editEntry(entry)}else{await select(await api<ProjectLog>(`/api/project-daily-logs/${id}`))}}catch(e){notify(messageOf(e),true)}}
async function printSaved(){if(!editing.value||local.dirty.value||exporting.value)return;exporting.value=true;try{await queuePrintExport('project_daily_logs',editing.value)}catch(e){error.value=messageOf(e)}finally{exporting.value=false}}
async function exportWord(){if(!editing.value||local.dirty.value||exporting.value)return;exporting.value=true;try{await queueWordExport('project_daily_logs',editing.value)}catch(e){error.value=messageOf(e)}finally{exporting.value=false}}
function appendNextPlan(text:string){entryForm.next_plan=appendPlan(entryForm.next_plan,text);entryDraft.markDirty()}
function closeEntry(){if(!entrySaving.value&&entryDraft.canLeave())entryOpen.value=false}
onMounted(()=>{const params=new URLSearchParams(location.hash.split('?')[1]||'');const requested=params.get('project_id')||'';if(params.get('log_date')&&/^\d{4}-\d{2}-\d{2}$/.test(params.get('log_date')!))date.value=params.get('log_date')!;project.value=ui.projects.some(p=>p.id===requested)?requested:ui.projects.find(p=>!isProjectReadOnly(p.id))?.id||ui.projects[0]?.id||'';void load()});watch(()=>props.revision,load)
defineExpose({canLeave,openEntity})
</script>
<template>
<div class="page-heading"><div><h1>工作日志</h1><p class="page-description">按人记录当天工作，汇总整个项目组的进展、工时和待协调事项。</p></div></div>
<JournalTabs active="project"/>
<form class="filter-bar" @submit.prevent="apply"><select v-model="project" :disabled="saving||generating" aria-label="项目日志所属项目" required><option value="" disabled>选择项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><input v-model="date" :disabled="saving||generating" type="date" aria-label="项目日志日期" required/><button class="button subtle">查看</button><button type="button" class="button primary" :disabled="projectReadonly||generating" @click="generate"><WandSparkles :size="16"/>{{generating?'正在汇总…':'生成项目日志'}}</button></form>
<p class="input-hint generator-hint">本机可为成员代填；已授权的局域网成员也可自行提交。生成汇总当前来源只产生草稿；保存后保留来源快照，重新汇总需要显式操作。</p>
<div v-if="error" class="error-banner" role="alert">{{error}}</div>
<section class="surface team-entry-surface"><div class="section-heading"><h2><Users :size="17"/> {{date}} 人员工作记录 <span class="count">{{entries.length}}</span></h2><button class="button subtle small" :disabled="projectReadonly" @click="editEntry()"><Plus :size="15"/>为成员填写</button></div><p v-if="loading" class="loading-message">正在读取项目日志…</p><div v-else-if="!entries.length" class="empty-state compact"><p>还没有当天的人员记录。可先为成员填写，也可从现有任务和工时生成草稿。</p></div><div v-else class="table-scroll"><table class="team-entry-table"><thead><tr><th>人员</th><th>完成工作</th><th>后续计划 / 阻碍</th><th class="right">操作</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.id"><td><strong>{{entry.person_name}}</strong><small>{{entry.task_ids.length}} 项关联任务</small></td><td class="team-content">{{entry.content||'未填写完成工作'}}</td><td class="team-content"><p>{{entry.next_plan||'未填写后续计划'}}</p><small v-if="entry.blockers" class="overdue">需协调：{{entry.blockers}}</small></td><td class="right"><button class="text-button" @click="editEntry(entry)">{{projectReadonly?'查看':'编辑'}}</button><button v-if="!projectReadonly" class="text-button" @click="removeEntry(entry)">回收</button></td></tr></tbody></table></div></section>
<div class="worklog-layout project-journal-layout"><aside class="surface saved-logs"><div class="section-heading"><h2>已保存项目日志 <span class="count">{{total}}</span></h2></div><div v-if="!logs.length" class="empty-state compact"><FilePenLine :size="30"/><p>保存后的项目日志会保留当时引用的人员记录、任务和工时版本。</p></div><div v-else class="log-list"><button v-for="log in logs" :key="log.id" :class="{selected:editing?.id===log.id}" @click="select(log)"><span class="log-date">{{log.log_date}}<span class="badge">项目日报</span></span><span>{{projectName(log.project_id)}}</span></button></div><Pager :offset="offset" :limit="limit" :total="total" @change="offset=$event;load()"/></aside>
<section class="surface log-editor"><template v-if="editor"><div class="section-heading"><div><h2>{{logForm.log_date}} 项目工作日志 <span v-if="local.dirty.value" class="draft-label">未保存</span></h2><p class="input-hint">{{projectName(logForm.project_id)}}<span v-if="readonly"> · 已结项或归档，只读</span></p></div><div class="row-actions"><button v-if="editing" class="button subtle small" :disabled="exporting||saving||local.dirty.value" :title="local.dirty.value?'请先保存修改':'导出已保存版本为 Word'" @click="exportWord">{{exporting?'正在创建…':'导出 Word'}}</button><button v-if="editing" type="button" class="button subtle small" :disabled="exporting||saving||local.dirty.value" @click="printSaved">打印 / PDF</button><button class="button subtle small" @click="downloadMarkdown(logForm.content,`${logForm.log_date}-项目工作日志.md`)"><Download :size="15"/>Markdown</button><button v-if="editing&&!readonly" class="button subtle small" @click="removeLog">回收</button><button v-if="!readonly" class="button primary small" :disabled="saving||!logForm.content.trim()" @click="save"><Save :size="15"/>{{saving?'正在保存…':'保存日志'}}</button></div></div>
<DraftNotice :value="local.available.value" :values="local.values.value" :error="local.storageError.value" :recovery="local.recovery.value" @select="local.select" @restore="local.restore" @force="local.restoreForced" @cancel-recovery="local.clearRecovery" @discard="local.discardAvailable"/><ConflictNotice :value="conflict.current.value" @keep="local.persist();conflict.clear()" @reload="reloadConflict"/>
<details class="journal-sources"><summary>汇总来源 · {{(source.people?.length||0)+(source.lan_people?.length||0)}} 人 · {{durationLabel(source.total_minutes||0)}}</summary><p class="input-hint">{{source.task_snapshot_semantics||'任务状态为生成草稿时的当前快照。'}}</p><p v-if="source.missing_people?.length" class="input-hint overdue">尚未填写：{{source.missing_people.join('、')}}</p><ul><li v-for="person in source.people" :key="person.person_name">{{person.person_name}}：{{durationLabel(person.minutes)}}，{{person.submitted?'已填写工作记录':'未填写工作记录'}}</li></ul><ul v-if="source.lan_people?.length"><li v-for="person in source.lan_people" :key="person.member_id">{{person.person_name}}（成员 {{person.member_id.slice(0,8)}}）：{{durationLabel(person.minutes)}}，{{person.submitted?'已提交':'当天未提交'}}</li></ul><p class="input-hint">引用 {{source.team_entries?.length||0}} 份代填记录、{{source.lan_entries?.length||0}} 份成员提交、{{source.time_entries?.length||0}} 条工时、{{source.tasks?.length||0}} 项任务；保存后来源版本不会随台账修改自动变化。</p></details>
<label class="sr-only" for="project-journal-content">项目日志正文</label><textarea id="project-journal-content" v-model="logForm.content" :readonly="readonly||saving||generating" class="markdown-editor" spellcheck="false"/><HistoryPanel v-if="editing" kind="project-daily-logs" :id="editing.id" :revision="editing.version"/></template><div v-else class="empty-state editor-empty"><FilePenLine :size="40"/><h2>汇总今天整个项目组的工作</h2><p>填写人员记录后生成草稿，或从左侧查看已保存的项目日志。</p></div></section></div>
<Modal :open="entryOpen" :title="editingEntry?'人员工作记录':'为成员填写工作记录'" wide @close="closeEntry"><form class="modal-body" @submit.prevent="saveEntry"><DraftNotice :value="entryDraft.available.value" :values="entryDraft.values.value" :error="entryDraft.storageError.value" :recovery="entryDraft.recovery.value" @select="entryDraft.select" @restore="entryDraft.restore" @force="entryDraft.restoreForced" @cancel-recovery="entryDraft.clearRecovery" @discard="entryDraft.discardAvailable"/><ConflictNotice :value="entryConflict.current.value" @keep="entryDraft.persist();entryConflict.clear()" @reload="reloadEntry"/>
<fieldset :disabled="entrySaving||isProjectReadOnly(entryForm.project_id)"><div class="form-row"><label>人员姓名 <span class="required">*</span><input v-model="entryForm.person_name" list="journal-people" required maxlength="100" placeholder="与任务负责人及工时人员保持一致"/><datalist id="journal-people"><option v-for="name in people" :key="name" :value="name"/></datalist></label><label>工作日期 <span class="required">*</span><input v-model="entryForm.log_date" type="date" required/></label></div><label>完成工作<textarea v-model="entryForm.content" rows="4" maxlength="20000" placeholder="当天完成的工作与产出"/></label><div class="form-row"><label>明日计划<textarea v-model="entryForm.next_plan" rows="3" maxlength="10000" placeholder="手动填写，或从任务和当天记录中选择"/><NextPlanPicker :date="entryForm.log_date" :project-id="entryForm.project_id" :assignee="entryForm.person_name" :disabled="entrySaving||isProjectReadOnly(entryForm.project_id)" @append="appendNextPlan"/></label><label>阻碍 / 需协调事项<textarea v-model="entryForm.blockers" rows="3" maxlength="10000"/></label></div><details class="journal-task-picker"><summary>关联任务（{{entryForm.task_ids.length}}）</summary><label v-for="task in tasks.filter(t=>!t.has_children)" :key="task.id" class="checkbox-label"><input v-model="entryForm.task_ids" type="checkbox" :value="task.id"/>{{task.wbs_code}} {{task.name}}<span class="muted">{{task.assignee||'未分配'}}</span></label></details></fieldset><p class="input-hint">同一项目、同一天、同一人员只保留一份有效记录。此处记录工作描述；实际工时请在工时页按人员登记。</p><HistoryPanel v-if="editingEntry" kind="team-daily-entries" :id="editingEntry.id" :revision="editingEntry.version"/><p v-if="entryError" class="form-error" role="alert">{{entryError}}</p><div class="modal-footer"><button v-if="!isProjectReadOnly(entryForm.project_id)" class="button primary" :disabled="entrySaving">{{entrySaving?'正在保存…':'保存人员记录'}}</button></div></form></Modal>
</template>
<style scoped>
.journal-mode{display:flex;gap:4px;border-bottom:1px solid var(--border);margin:-8px 0 22px}.journal-mode a{padding:12px 20px;font-size:13px;color:var(--muted);border-bottom:2px solid transparent}.journal-mode a[aria-current]{color:var(--blue);border-color:var(--blue);font-weight:600}.team-entry-surface{margin-bottom:24px}.team-entry-table{min-width:740px}.team-entry-table th:first-child{width:130px}.team-content{white-space:pre-wrap;min-width:200px;line-height:1.8}.team-entry-table .text-button+.text-button{margin-left:14px}.journal-sources{padding:14px 22px;background:#f5f8fc;border-bottom:1px solid var(--border);font-size:12px}.journal-sources summary{cursor:pointer;color:#486585}.journal-sources p,.journal-sources ul{margin-top:10px;line-height:1.8}.journal-task-picker{font-size:13px;max-height:260px;overflow:auto}.journal-task-picker summary{cursor:pointer;margin:12px 0}.journal-task-picker label{margin:8px 0}.project-journal-layout .row-actions{flex-wrap:wrap}.project-journal-layout{margin-top:24px}
</style>
